        size_t chunk = 1<<20;
        while (off < n) {
            size_t m = n - off < chunk ? n - off : chunk;
            CC_SHA256_Update(&ctx, data+off, (CC_LONG)m);
            off += m;
        }
        CC_SHA256_Final(out, &ctx);
    }
    t1 = now();
    printf("CC chunked: %.2f ms\n", (t1-t0)/iters*1000);
    return 0;
}
