{"command":"cat > build/sha256_avx2.c << 'EOF'
/* Two-block interleaved AVX2 SHA-256.
 * Processes 2 independent 64-byte blocks' schedules in SIMD,
 * but compression state is chained so we still do rounds scalar... 
 * Actually for true speed we need the message schedule + rounds interleaved
 * like OpenSSL. This is a simpler experiment: SIMD message schedule for one block
 * + scalar rounds, to see if we can beat 42ms. Probably not, but let's measure.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>
#include <openssl/sha.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t Ch(uint32_t x,uint32_t y,uint32_t z){ return (x&y)^(~x&z); }
static inline uint32_t Maj(uint32_t x,uint32_t y,uint32_t z){ return (x&y)^(x&z)^(y&z); }
static inline uint32_t S0(uint32_t x){ return rotr(x,2)^rotr(x,13)^rotr(x,22); }
static inline uint32_t S1(uint32_t x){ return rotr(x,6)^rotr(x,11)^rotr(x,25); }
static inline uint32_t s0(uint32_t x){ return rotr(x,7)^rotr(x,18)^(x>>3); }
static inline uint32_t s1(uint32_t x){ return rotr(x,17)^rotr(x,19)^(x>>10); }

static void sha256_block_scalar(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i=0;i<16;i++) {
        w[i] = ((uint32_t)block[i*4]<<24)|((uint32_t)block[i*4+1]<<16)|((uint32_t)block[i*4+2]<<8)|block[i*4+3];
    }
    for (int i=16;i<64;i++) w[i] = s1(w[i-2]) + w[i-7] + s0(w[i-15]) + w[i-16];
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i=0;i<64;i++) {
        uint32_t t1 = h + S1(e) + Ch(e,f,g) + K[i] + w[i];
        uint32_t t2 = S0(a) + Maj(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

/* AVX2 message schedule: compute W in vectors. Still scalar rounds. */
static void sha256_block_avx2sched(uint32_t state[8], const uint8_t block[64]) {
    __m128i bswap_mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+0)), bswap_mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), bswap_mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), bswap_mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), bswap_mask);

    uint32_t w[64];
    _mm_storeu_si128((__m128i*)(w+0), w0);
    _mm_storeu_si128((__m128i*)(w+4), w1);
    _mm_storeu_si128((__m128i*)(w+8), w2);
    _mm_storeu_si128((__m128i*)(w+12), w3);

    /* vectorized schedule using the standard SSE approach expanded to produce 4 words at a time */
    for (int i=16;i<64;i+=4) {
        /* scalar fallback for correctness first; we'll replace */
        w[i]   = s1(w[i-2]) + w[i-7] + s0(w[i-15]) + w[i-16];
        w[i+1] = s1(w[i-1]) + w[i-6] + s0(w[i-14]) + w[i-15];
        w[i+2] = s1(w[i])   + w[i-5] + s0(w[i-13]) + w[i-14];
        w[i+3] = s1(w[i+1]) + w[i-4] + s0(w[i-12]) + w[i-13];
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i=0;i<64;i++) {
        uint32_t t1 = h + S1(e) + Ch(e,f,g) + K[i] + w[i];
        uint32_t t2 = S0(a) + Maj(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void hash_scalar(const uint8_t *data, size_t n, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t blocks = n/64;
    for (size_t i=0;i<blocks;i++) sha256_block_scalar(state, data+i*64);
    /* ignore padding for bench of full blocks; n is multiple of 64 for speed test of compress only */
    for (int i=0;i<8;i++) {
        out[i*4]=(state[i]>>24)&0xff; out[i*4+1]=(state[i]>>16)&0xff; out[i*4+2]=(state[i]>>8)&0xff; out[i*4+3]=state[i]&0xff;
    }
}

int main() {
    size_t n = 20ull*1024*1024;
    uint8_t *data = malloc(n);
    memset(data, 0x5a, n);
    uint8_t out1[32], out2[32];
    int iters = 3;
    double t0 = now();
    for(int i=0;i<iters;i++) hash_scalar(data, n, out1);
    double t1 = now();
    printf("scalar C: %.2f ms\n", (t1-t0)/iters*1000);

    t0 = now();
    for(int i=0;i<iters;i++) SHA256(data, n, out2);
    t1 = now();
    printf("openssl: %.2f ms\n", (t1-t0)/iters*1000);
    printf("(scalar ignores padding so digest won't match full SHA256)\n");
    return 0;
}
EOF
clang -O3 -mavx2 -mbmi2 -o build/sha256_avx2 build/sha256_avx2.c -lcrypto && ./build/sha256_avx2"}

