        uint32_t s0v = rotr(x,7)^rotr(x,18)^(x>>3);
        x = w[i-2];
        uint32_t s1v = rotr(x,17)^rotr(x,19)^(x>>10);
        w[i] = s1v + w[i-7] + s0v + w[i-16];
