    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

void sha256_full(const uint8_t *data, size_t n, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t off = 0;
    while (off + 64 <= n) {
        block_clean(state, data+off);
        off += 64;
    }
    uint8_t tail[128];
    size_t rem = n - off;
    if (rem) memcpy(tail, data+off, rem);
    tail[rem] = 0x80;
    size_t pad_len = (rem < 56) ? 64 : 128;
    memset(tail+rem+1, 0, pad_len - rem - 1 - 8);
    uint64_t bits = (uint64_t)n * 8;
    for (int i=0;i<8;i++) tail[pad_len-1-i] = (uint8_t)(bits >> (8*i));
    block_clean(state, tail);
    if (pad_len == 128) block_clean(state, tail+64);
    for (int i=0;i<8;i++) {
        out[4*i]=state[i]>>24; out[4*i+1]=state[i]>>16; out[4*i+2]=state[i]>>8; out[4*i+3]=state[i];
