        if (memcmp(o1,o2,32)) { printf("mismatch %zu\n", lens[i]); return 1; }
    }
    printf("ok\n");
    volatile uint8_t sink = 0;
    int iters = 4;
    double t0 = now();
    for (int i=0;i<iters;i++) { sha256_full(data, n, o1); sink += o1[0]; }
    printf("sse-load: %.2f ms sink=%u\n", (now()-t0)/iters*1000, sink);
    t0 = now();
    for (int i=0;i<iters;i++) { SHA256(data, n, o2); sink += o2[0]; }
    printf("openssl: %.2f ms sink=%u\n", (now()-t0)/iters*1000, sink);
    return 0;
}
