/* Message schedule producing 64 words using SSE, stored to w[64]. */
static inline void schedule(uint32_t w[64], const uint8_t block[64]) {
    __m128i mask = _mm_load_si128((const __m128i*)BSWAP);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+0)), mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), mask);
