    _mm_store_si128((__m128i*)(w+4), w1);
    _mm_store_si128((__m128i*)(w+8), w2);
    _mm_store_si128((__m128i*)(w+12), w3);

    /* Extend. Classic SSE algorithm from Intel SHA-256 whitepaper / public domain.
       For each group of 4 words starting at index 16,20,...,60:
         s0 = sigma0( w[i-15], w[i-14], w[i-13], w[i-12] )
         s1 = sigma1( w[i-2],  w[i-1],  w[i],    w[i+1] )  -- partial, needs fixup
       We'll use the two-step method that is known correct:

       // from https://www.intel.com/content/www/us/en/developer/articles/technical/sha-256-implementations-paper.html
       // adapted
