    __m128i cur[16];
    cur[0]=w0; cur[1]=w1; cur[2]=w2; cur[3]=w3;
    for (int i = 4; i < 16; i++) {
        __m128i a = cur[i-4];
        __m128i b = cur[i-3];
        __m128i c = cur[i-2];
        __m128i d = cur[i-1];
        /* w[i-16] = a
           w[i-15..i-12] = alignr(b, a, 4)
           w[i-7..i-4]   = alignr(d, c, 4)
           w[i-2],w[i-1],w[i],w[i+1] needs special handling
        */
        __m128i s0 = sigma0(_mm_alignr_epi8(b, a, 4));
        __m128i t = _mm_add_epi32(a, s0);
        t = _mm_add_epi32(t, _mm_alignr_epi8(d, c, 4));
        /* sigma1 of (w[i-2], w[i-1], w[i], w[i+1])
           First compute sigma1 of (w[i-2], w[i-1], 0, 0) = srli_si128(d, 8)
           That gives the first two words of the result correctly if we then
           add and shift... The standard fixup:
        */
        __m128i s1 = sigma1(_mm_srli_si128(d, 8));
        __m128i wi = _mm_add_epi32(t, s1);
        /* Now wi[0], wi[1] are correct (w[i], w[i+1]). wi[2], wi[3] are not
           because s1 used zeros. Fix:
           s1_full for words 2,3 depends on w[i], w[i+1] which we now have.
           w[i+2] = s1(w[i]) + w[i-5] + s0(w[i-13]) + w[i-14]
           Those are already in `t` for lanes 2 and 3 (t was computed for all 4
           lanes from s0 and w[i-7] which don't depend on new words).
           So lanes 2,3 of t are correct partial sums; we need sigma1(w[i]) and sigma1(w[i+1]).
        */
        __m128i s1b = sigma1(_mm_alignr_epi8(wi, d, 8)); /* (w[i-2]? let's verify empirically) */
        /* alignr(wi, d, 8) = words: d[2], d[3], wi[0], wi[1] = w[i-2], w[i-1], w[i], w[i+1]
           sigma1 of that is exactly what we need for all 4 new words!
           But wi depends on s1 which depends on this... circular for lanes 0,1?
           Lanes 0,1 of alignr(wi, d, 8) are d[2], d[3] = w[i-2], w[i-1], independent of wi.
           Lanes 2,3 are wi[0], wi[1], which we computed from the partial s1.
           So sigma1(alignr(wi,d,8)) lane0,1 == sigma1(w[i-2]), sigma1(w[i-1]) which we already
           added. Lane2,3 are the missing ones.
           We should take lanes 0,1 from `wi` and lanes 2,3 from t+sigma1(alignr).
        */
        __m128i s1full = sigma1(_mm_alignr_epi8(wi, d, 8));
        __m128i wi2 = _mm_add_epi32(t, s1full);
