static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main(){
    size_t n = 20ull*1024*1024;
    uint8_t *data = aligned_alloc(32, n);
    memset(data, 0xab, n);
    uint8_t out[32];
    int iters=3;
    double t0=now();
    volatile uint8_t sink=0;
    for(int i=0;i<iters;i++){ SHA256(data,n,out); sink+=out[0]; }
    printf("openssl %.2f ms\n", (now()-t0)/iters*1000);

    /* 8-way independent SHA256 via OpenSSL in threads already showed ~1 hash latency for 2 hashes.
       So 8 independent 20MB hashes in parallel would take ~about 1-2 hash times if bandwidth allows.
       Let's measure memory bandwidth. */
    t0=now();
    uint64_t acc=0;
    for(int i=0;i<iters;i++){
        uint64_t *p=(uint64_t*)data;
        size_t cnt=n/8;
        uint64_t a=0;
        for(size_t j=0;j<cnt;j++) a+=p[j];
        acc+=a;
    }
    printf("read bandwidth: %.2f ms (%.1f GB/s) acc=%llu\n", (now()-t0)/iters*1000, (n/1e9)/((now()-t0)/iters), (unsigned long long)acc);
    return 0;
}
