#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

/*
 * AVX2 SHA-256, one block at a time, message schedule in YMM registers.
 * Layout follows the Go/OpenSSL approach:
 *   After byte swap, 4 YMMs hold 16 words? A block is 64 bytes = 16 words = 2 YMMs.
 *   OpenSSL/Go transpose two blocks. We'll do one block with XMM/YMM schedule
 *   of 4 words at a time but using AVX2 vpsrld/vpxor which can be faster,
 *   and BMI2 rounds fully unrolled via macros.
 *
 * Goal: beat 42ms. If we get ~25ms that's only 1.6x. Still useful to know.
 */

static const uint32_t K[64] __attribute__((aligned(32))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) __builtin_rotateright32((x),(n))
#define S0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))
#define S1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))
#define CH(x,y,z) (((x)&(y))^((~(x))&(z)))
#define MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))

#define RND(a,b,c,d,e,f,g,h,i) do { \
    uint32_t t1 = (h) + S1(e) + CH(e,f,g) + K[i] + w[i]; \
    uint32_t t2 = S0(a) + MAJ(a,b,c); \
    (h)=g; (g)=f; (f)=e; (e)=(d)+t1; (d)=c; (c)=b; (b)=a; (a)=t1+t2; \
} while(0)

static inline __m128i sig0(__m128i x) {
    __m128i r7  = _mm_or_si128(_mm_srli_epi32(x,7),  _mm_slli_epi32(x,25));
    __m128i r18 = _mm_or_si128(_mm_srli_epi32(x,18), _mm_slli_epi32(x,14));
    return _mm_xor_si128(_mm_xor_si128(r7, r18), _mm_srli_epi32(x,3));
}
static inline __m128i sig1(__m128i x) {
    __m128i r17 = _mm_or_si128(_mm_srli_epi32(x,17), _mm_slli_epi32(x,15));
    __m128i r19 = _mm_or_si128(_mm_srli_epi32(x,19), _mm_slli_epi32(x,13));
    return _mm_xor_si128(_mm_xor_si128(r17, r19), _mm_srli_epi32(x,10));
}

/* Known-correct SSE schedule from the earlier experiment that matched openssl. */
static inline void sched(uint32_t w[64], const uint8_t block[64]) {
    const __m128i mask = _mm_setr_epi8(3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+0)), mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), mask);
    _mm_storeu_si128((__m128i*)(w+0), w0);
    _mm_storeu_si128((__m128i*)(w+4), w1);
    _mm_storeu_si128((__m128i*)(w+8), w2);
    _mm_storeu_si128((__m128i*)(w+12), w3);
    __m128i cur0=w0, cur1=w1, cur2=w2, cur3=w3;
    for (int i=4;i<16;i++) {
        __m128i a=cur0, b=cur1, c=cur2, d=cur3;
        __m128i s0 = sig0(_mm_alignr_epi8(b, a, 4));
        __m128i t = _mm_add_epi32(a, s0);
        t = _mm_add_epi32(t, _mm_alignr_epi8(d, c, 4));
        __m128i s1 = sig1(_mm_srli_si128(d, 8));
        __m128i wi = _mm_add_epi32(t, s1);
        __m128i s1full = sig1(_mm_alignr_epi8(wi, d, 8));
        __m128i wi2 = _mm_add_epi32(t, s1full);
        wi = _mm_blend_epi16(wi, wi2, 0xF0);
        _mm_storeu_si128((__m128i*)(w+i*4), wi);
        cur0=cur1; cur1=cur2; cur2=cur3; cur3=wi;
    }
}

static void block(uint32_t st[8], const uint8_t data[64]) {
    uint32_t w[64];
    sched(w, data);
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    /* manual unroll 4 at a time to help compiler */
    for (int i=0;i<64;i+=4) {
        RND(a,b,c,d,e,f,g,h,i);
        RND(a,b,c,d,e,f,g,h,i+1);
        RND(a,b,c,d,e,f,g,h,i+2);
        RND(a,b,c,d,e,f,g,h,i+3);
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

void sha256_full(const uint8_t *data, size_t n, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    const uint8_t *p = data;
    const uint8_t *end = data + (n & ~((size_t)63));
    while (p < end) { block(state, p); p += 64; }
    uint8_t tail[128];
    size_t rem = n & 63;
    if (rem) memcpy(tail, p, rem);
    tail[rem] = 0x80;
    size_t pad_len = (rem < 56) ? 64 : 128;
    memset(tail+rem+1, 0, pad_len - rem - 9);
    uint64_t bits = (uint64_t)n * 8;
    for (int i=0;i<8;i++) tail[pad_len-1-i] = (uint8_t)(bits >> (8*i));
    block(state, tail);
    if (pad_len==128) block(state, tail+64);
    for (int i=0;i<8;i++) {
        uint32_t v = state[i];
        out[4*i]=v>>24; out[4*i+1]=v>>16; out[4*i+2]=v>>8; out[4*i+3]=v;
    }
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main(){
    size_t n=20ull*1024*1024;
    uint8_t *data=malloc(n+80);
    memset(data,0x5a,n+80);
    uint8_t o1[32],o2[32];
    size_t lens[]={0,1,55,56,63,64,65,100,1000,n,n+3,n+63};
    for(int i=0;i<12;i++){
        sha256_full(data,lens[i],o1);
        SHA256(data,lens[i],o2);
        if(memcmp(o1,o2,32)){printf("bad %zu\n",lens[i]);return 1;}
    }
    printf("ok\n");
    volatile unsigned sink=0;
    int iters=4;
    double t0=now();
    for(int i=0;i<iters;i++){sha256_full(data,n,o1); sink+=o1[0];}
    printf("ours %.2f ms\n",(now()-t0)/iters*1000);
    t0=now();
    for(int i=0;i<iters;i++){SHA256(data,n,o2); sink+=o2[0];}
    printf("openssl %.2f sink %u\n",(now()-t0)/iters*1000,sink);
    return 0;
}
EOF
