void fast_sha256(const uint8_t *data, size_t n, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t off = 0;
    while (off + 64 <= n) {
        compress(st, data + off);
        off += 64;
    }
    uint8_t tail[128];
    size_t rem = n - off;
    if (rem) memcpy(tail, data + off, rem);
    tail[rem] = 0x80;
    size_t pad_len = (rem < 56) ? 64 : 128;
    memset(tail + rem + 1, 0, pad_len - rem - 9);
    uint64_t bits = (uint64_t)n * 8;
    for (int i = 0; i < 8; i++) tail[pad_len - 1 - i] = (uint8_t)(bits >> (8 * i));
    compress(st, tail);
    if (pad_len == 128) compress(st, tail + 64);
    for (int i = 0; i < 8; i++) {
        out[4*i]   = (uint8_t)(st[i] >> 24);
        out[4*i+1] = (uint8_t)(st[i] >> 16);
        out[4*i+2] = (uint8_t)(st[i] >> 8);
        out[4*i+3] = (uint8_t)st[i];
    }
}
